-- 2902 🏋️ Exercises from the book "jose-mourinho-attacking-sessions-114-practices-from-goal-analysis-of-real-madrid" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'jose-mourinho-attacking-sessions-114-practices-from-goal-analysis-of-real-madrid');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Passing and one-two combination star', 'passing_unopposed', 'unopposed', 'in_possession', 19, 19, 'Session 1: Practice 1', 'Mourinho (Real Madrid)', 'Builds one-two combinations and accurate team passing.', '30 x 30 yard square, 7 players on 6 cones with 2 mannequins; balls start with player 1 at the bottom cone, cones about 10-15 m apart.', 'Player 1 passes to 2 and takes 2''s spot; 2 sets inside to 3 who plays back and moves on to 4''s spot, and so on round the shape; the other side repeats it and the last pass goes to 7 who restarts as player 1.', NULL, NULL, 'Directional first touch with the second touch a pass; open body, receive and pass with back foot; right surface for each distance; pass weight and talk.', '7 players', 7, 7, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 10),
  ('Quick one-two combination circuit', 'passing_unopposed', 'unopposed', 'in_possession', 20, 20, 'Session 1: Practice 2', 'Mourinho (Real Madrid)', 'Builds one-two combinations and accurate team passing at speed.', 'Same square as the previous practice with the mannequins removed; players at positions A to G.', 'A passes to B, B lays it back to A running onto it, A passes to C; C sets back for B who runs on and plays to D; the chain of give-and-gos continues round the shape until E''s last pass to G who starts again; players follow on to the next spot after their second pass.', 'One touch.', 'Put an extra player at D and run two balls at once, starting from A and D.', 'Accurate, well weighted passes; rhythm and timing of movement with the pass; heads up and talk.', '7-8 players', 7, 8, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 20),
  ('Full back one-two and final ball', 'combination', 'unopposed', 'in_possession', 21, 21, 'Session 1: Practice 3', 'Mourinho (Real Madrid)', 'Rehearses a flank one-two that ends with a through ball behind a deep line and a shot.', 'Half pitch with keeper, 4 mannequins as a back line; centre back/midfielder (4), two full backs at cone gates, two wide forwards and a striker (9).', '4 plays wide to the full back (3) who dribbles through the cone gate and passes to the wide forward (11); 3 runs inside for the return, drives in and slides a timed ball behind the mannequins for 9, who bends a horizontal-then-diagonal run to stay onside and shoots.', NULL, NULL, 'Pass accuracy and weight; check away from the marker before coming to the ball; full back''s first touch forward through the cones and dribble inside at speed.', '6+ players + GK', 7, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Winger one-two with two final-ball options', 'combination', 'unopposed', 'in_possession', 22, 22, 'Session 1: Practice 4', 'Mourinho (Real Madrid)', 'Rehearses a flank one-two with a choice of runners behind the defensive line.', 'Same half pitch and mannequins as practice 3, now with 2 central midfielders (6, 8) feeding; wide forwards, striker and target zones 1 and 2 behind the line.', '6 plays to the wide forward (11) who does a one-two with the striker (9) and drives inside; option 1 is a pass behind for the far-side forward (7) to shoot, option 2 is a ball into the channel for 9 to cross while 7 attacks the near post, 11 the far post and the midfielders arrive at the edge of the box. Run from both sides.', NULL, NULL, 'Runs behind the line must be sharp, curved or angled and timed to beat offside.', '8+ players + GK', 9, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Double one-two and final ball', 'combination', 'unopposed', 'in_possession', 23, 23, 'Session 1: Practice 5', 'Mourinho (Real Madrid)', 'Rehearses a two-stage combination through midfield and striker into a first-time ball behind the line.', 'Half pitch with keeper and 4 mannequins; wide forward (11), central midfielders (6, 8), striker and far forward (7), target zones 1 and 2.', 'The wide forward plays back to 6, who feeds the striker; 11 makes the same inside run and gets the ball back, then plays first time either into the striker on the left channel or between full back and centre back for 7 to shoot.', NULL, NULL, NULL, '6+ players + GK', 7, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 50),
  ('7v7+3 one-twos into final zones', 'small_sided_game', 'overload', 'in_possession', 24, 24, 'Session 1: Practice 6', 'Mourinho (Real Madrid)', 'Uses one-twos with neutrals to break pressure and play the final ball behind the line.', '70 x 55 yard area in 3 zones: central zone 32 x 55, two end final zones 16 x 52, goals with keepers; 6 v 6 in the middle in a 2-3-1 shape, 3 neutrals (1 central, 1 in each final zone).', 'The team on the ball must combine with a one-two and a third-man move involving a neutral before a final ball can go into the final zone for a teammate to run on and shoot.', 'Final zone options: no defenders but limited touches; passive defenders; one fewer defender than attackers with limited touches for attackers; fully active defenders with unlimited touches.', 'Work through the four final-zone rule options.', 'One-twos and third-man combinations to escape pressure and go forward faster; quick, accurate finish in the final zone.', '7v7+3 neutrals (incl. GKs)', 17, 17, '70 x 55 yards', 64.0, 50.3, NULL, true, true, true, NULL, 60),
  ('Inside support runs 4-zone game', 'phase_of_play', 'opposed', 'in_possession', 25, 26, 'Session 1: Practice 7', 'Mourinho (Real Madrid)', 'Builds one-twos and third-man runs to get the final ball in behind a deep back four.', 'Half pitch split into 4 zones (two side channels); white team in a 2-2-3-1/4-3-1 with keeper attacks a full goal, red in a 4-4 defends it and counters to 3 goals on the halfway line (1 full size centre, 2 mini). 9 v 9.', 'Whites keep the ball and use one-twos and third-man runs to create chances in the final zone behind the reds; only the wide players (2, 3, 7, 11) may use the side channels; reds counter into any halfway goal; restarts always from the white keeper.', 'Reds'' wide players: banned from the central zone, then passive there, then fully active; reds may tackle but not intercept passes; reds free; finally whites defend only the central goal.', 'Step through the six rule options.', 'Angle and distance of support; sharp inside moves by wide forwards; mix of passes to feet and into space; final pass and run timed to beat offside; reds'' two lines of four press and block passes together.', '9v9', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Short and long one-touch passing circuit', 'passing_unopposed', 'unopposed', 'in_possession', 29, 29, 'Session 2: Practice 1', 'Mourinho (Real Madrid)', 'Develops a one-touch passing game mixing short and long passes.', '30 x 30 yard area, 7 players on 6 cones (one at each end, four at the sides), balls with player 1.', '1 plays long to 3, 3 sets short to 2, 2 plays long to 4, 4 plays one touch to 6, 6 to 5 and 5 back to the start where 7 becomes the new 1; everyone moves on one position after passing.', 'Build down to one touch.', 'Shorten time between touch and pass, then one touch.', 'First touch on the move; weight passes just in front of the receiver; high tempo.', '7 players', 7, 7, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 80),
  ('Quick combination, third-man run and finish', 'combination', 'unopposed', 'in_possession', 30, 30, 'Session 2: Practice 2', 'Mourinho (Real Madrid)', 'Develops one-twos with third-man runs ending in a shot.', '40 x 40 yard area split into 2 halves, each with a goal and keeper; two groups of 5 positions, one working from the right, one from the left.', '1 passes to 3, 3 lays it first time back to 2, 2 plays diagonally into 4; while that ball travels 5 makes the opposite diagonal run, gets 4''s pass and shoots.', NULL, NULL, 'Third-man runner starts as the ball travels from 2 to 4; pass weight lets the runner go on without slowing; 3''s pass cushioned so 2 can step onto it.', '10 players + 2 GKs', 12, 12, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 90),
  ('Functional third-man run, final ball, finish', 'combination', 'unopposed', 'in_possession', 31, 31, 'Session 2: Practice 3', 'Mourinho (Real Madrid)', 'Rehearses a team combination with a third-man run behind the defensive line.', 'Half pitch with keeper and 4 mannequins as the back line; centre back/midfielder, full backs, wide forwards, attacking midfielder and striker in position.', 'Centre back plays diagonally to the wide forward who plays first time to the full back (or supporting midfielder); he passes into the striker and, as it travels, the attacking midfielder makes an opposite diagonal run behind the mannequins to take the striker''s final ball and shoot.', NULL, NULL, 'Check away to make space before receiving; first pass firm to feet, second cushioned; third-man run starts as the ball goes to the striker; final pass and run timed together.', '7+ players + GK', 8, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('7v7+5 third-man runs into final zones', 'small_sided_game', 'overload', 'in_possession', 32, 33, 'Session 2: Practice 4', 'Mourinho (Real Madrid)', 'Develops one-twos and third-man runs to get in behind and score.', '70 x 55 yard area in 3 zones: central zone 55 x 34, final zones 55 x 18, goals with keepers; 6 v 6 in a 2-3-1 shape in the middle plus 5 neutrals with the team on the ball.', 'To get into a final zone the team in possession must play a one-two with a neutral while another player makes a third-man run to receive behind and shoot.', 'Final zone options: no defenders but limited touches; passive defenders; one fewer defender than attackers with limited touches; fully active with unlimited touches.', 'Work through the four final-zone rule options.', 'Support angle and distance; mix of passes to feet, into space and one-twos; eye contact and call for it; timing of runs and passes into the final zone; quick, accurate first-time shots.', '7v7+5 neutrals (incl. GKs)', 19, 19, '70 x 55 yards', 64.0, 50.3, NULL, true, true, true, NULL, 110),
  ('Third-man runs 4-zone 9v9 game', 'phase_of_play', 'opposed', 'in_possession', 34, 35, 'Session 2: Practice 5', 'Mourinho (Real Madrid)', 'Develops one-twos with third-man runs against a deep back four.', 'Half pitch in 4 zones with side channels; white 2-2-3-1 with keeper attacks a full goal, red 4-4 defends it and counters to 3 goals on the halfway line (1 full size, 2 mini). 9 v 9.', 'Only wide players (2, 3, 7, 11) use the side channels; to enter the final zone whites need a one-two plus a third-man run to receive behind the line; reds can defend in the final zone once the ball is played in and counter at the halfway goals.', 'Reds must score within 6-8 passes or 8-10 seconds; mini goal 1 point, big goal 2. Rule options as practice 7 of session 1: reds'' wide players barred, passive, then active centrally; tackle but no interceptions; free play; one goal only.', 'Step through the six rule options.', 'Support positioning and distance; check away before receiving to feet or in space.', '9v9', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Dribble inside for third-man overlap', 'passing_unopposed', 'unopposed', 'in_possession', 38, 38, 'Session 3: Practice 1', 'Mourinho (Real Madrid)', 'Develops the overlap run created by a teammate dribbling inside.', '8 x 16 yard grid with cones, 3 players; run as Stage 1 (from the right) and Stage 2 (from the left).', '1 passes to 2 and overlaps; 2 dribbles inside and passes to 3, who plays one touch into the path of the overlapping 1. Players rotate cones and repeat from the other side.', 'One-touch release from player 3.', 'Stage 2 mirrors it from the opposite side.', 'Overlap starts as soon as the first pass goes; communicate when to release so the ball is weighted out in front; sharp dribble inside to create room.', '3 players', 3, 3, '8 x 16 yards', 14.6, 7.3, NULL, false, false, false, NULL, 130),
  ('Dribble inside, overlap and finish', 'combination', 'unopposed', 'in_possession', 39, 39, 'Session 3: Practice 2', 'Mourinho (Real Madrid)', 'Adds a finish to the dribble-inside and overlap pattern.', 'Two areas side by side in front of two goals with keepers; group A works from the left, group B from the right.', 'Same pattern as the 3-player overlap drill, but the overlapping player receives near goal and shoots past the keeper; players work from both sides.', NULL, NULL, 'Finish with both feet; one touch when possible.', '6 players + 2 GKs', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Midfielder overlap and striker''s final ball', 'combination', 'unopposed', 'in_possession', 40, 40, 'Session 3: Practice 3', 'Mourinho (Real Madrid)', 'Develops a third-man overlap by a central midfielder behind the line.', 'Half pitch with keeper and 4 mannequins; full backs (2, 3), central midfielders (6, 8), attacking midfielder (10), wide forwards (7, 11) and striker (9).', 'Left back plays into 8, who steps up, passes to 10 and overlaps round him; 10 feeds the striker who plays first time behind the mannequins for 8 to shoot. Repeat on the other side from the right back to 6.', NULL, NULL, 'Full back''s pass firm into space for 8 to run onto; 8 sets off as soon as he passes; striker''s ball weighted and timed for the run.', '8+ players + GK', 9, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Winger dribbles inside, midfielder overlaps', 'combination', 'unopposed', 'in_possession', 41, 41, 'Session 3: Practice 4', 'Mourinho (Real Madrid)', 'Uses a winger''s inside dribble to free a midfielder''s overlapping run behind the line.', 'As practice 3: half pitch, keeper, 4 mannequins, full backs, central midfielders, wide forwards, 10 and striker.', 'Left back plays to 8, who passes to the left forward (11) and overlaps round him; 11 dribbles inside and plays into the striker, who returns it first time behind the line for 8 to shoot. Repeat on the right via 6 and 7.', NULL, NULL, NULL, '8+ players + GK', 9, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Overlap with striker set to 10', 'combination', 'unopposed', 'in_possession', 42, 42, 'Session 3: Practice 5', 'Mourinho (Real Madrid)', 'Adds a back-to-goal lay-off from the striker before the final ball behind.', 'As practice 4: half pitch, keeper, 4 mannequins, full set of midfield and attacking positions.', 'Left back to 8, 8 to the left forward and overlaps; 11 dribbles in and plays to the striker, who with his back to goal sets it first time to 10, and 10 slides it behind the line for the running 8 to shoot. Repeat on the right side.', NULL, NULL, NULL, '8+ players + GK', 9, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Overlapping runs into final zones SSG', 'small_sided_game', 'overload', 'in_possession', 43, 44, 'Session 3: Practice 6', 'Mourinho (Real Madrid)', 'Develops third-man overlapping runs to receive in behind and score.', '70 x 55 yard area in 3 zones (central 55 x 34, final zones 55 x 18), goals with keepers; 6 v 6 in a 2-3-1 shape plus 5 neutrals with the team on the ball, two of them on the sides.', 'A player may only enter a final zone by receiving after making a third-man overlapping run, then finishes.', 'Final zone options: no defenders but limited touches; passive defenders; one fewer defender than attackers with limited touches; fully active.', 'Variation (Practice 7): only 3 neutrals, 1 central and 2 on the sides.', 'Support angle and distance; mix of passes; eye contact and call for it; timing of runs into the final zone; quick first-time shots aimed for accuracy.', '7v7+5 neutrals (incl. GKs)', 17, 19, '70 x 55 yards', 64.0, 50.3, NULL, true, true, true, NULL, 180),
  ('Cross-and-finish double-goal circuit', 'finishing', 'unopposed', 'in_possession', 48, 49, 'Session 4: Practice 1', 'Mourinho (Real Madrid)', 'Develops crossing and finishing off combination play with timed runs.', '40 x 40 yards with 2 goals and 2 keepers; 12 players on 6 starting spots: 2 at each end on the flank (A and D) and 4 in the middle (B and C pairs).', 'Both A''s start with a ball and pass to the facing B, who sets first time to the nearby C; C passes to D at the far end, and A, who has sprinted on, takes D''s ball first time and crosses; the C''s curl to the back post and the B''s attack the near post of the other goal. Players rotate and the drill switches to cross from the left.', NULL, NULL, 'Mix of long passes to feet, cushioned short ones and balls into space; check away to make space for one touch; same timing on both sides; cross and near/far post runs coordinated for first-time finishes.', '12 players + 2 GKs', 14, 14, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 190),
  ('Switch play and cross pattern', 'combination', 'unopposed', 'in_possession', 50, 50, 'Session 4: Practice 2', 'Mourinho (Real Madrid)', 'Rehearses switching the point of attack to the far winger and filling the box for the cross.', 'Two-thirds of a pitch with keeper and 4 mannequins as defenders; 7 players from the 4-2-3-1: one centre back (4), midfielders 6, 8, 10, striker 9 and wide forwards 7 and 11.', '4 to 6, 6 straight into 10, 10 first time to 8; 9 drops to receive from 8 and plays first time to 11 coming inside, who switches with a long ball to 7 on the right; 7 dribbles down the line and crosses as 9 attacks the near post, 10 the far post, and 8 and 11 arrive late.', NULL, NULL, 'Check away from start spots before receiving; correct support positions and distances; switch pass accurate and played for 7 to run onto; rhythm of movement and passing.', '7 players + GK', 8, NULL, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('1v1 flanks, 3v2 middle, cross and finish', 'finishing', 'opposed', 'in_possession', 51, 52, 'Session 4: Practice 3', 'Mourinho (Real Madrid)', 'Develops 1v1 play on the flank, crossing, finishing and timed runs into the box.', 'Half pitch split into 3 zones, length twice the box (36 yards); 2v2 in the central zone, 1v1 in each side zone; keeper in goal and a coach with balls.', 'Central midfielder (8) starts with the ball and passes to either flank; the wide forward beats his full back and crosses into the box where 2v2 becomes 3v2(+1) as 8 runs forward followed by a passive defender (6).', 'Defenders passive; then centre backs passive and full backs active; then all fully active.', 'Variation (Practice 4): the blue 6 is fully active to stop 8 passing wide, and the far-side wide forward also attacks the box; blue full back first barred from, then allowed into, the central zone.', 'Check away before receiving or finding space in the box; good dribbling to win the 1v1; time runs to finish first time; one near post, one far post; accurate crossing and finishing under pressure.', '6v5 + GK', 12, NULL, 'half pitch, zones 36 yards long', 32.9, NULL, NULL, true, true, true, NULL, 210),
  ('2v2 flank zones crossing game', 'finishing', 'opposed', 'in_possession', 53, 54, 'Session 4: Practice 5', 'Mourinho (Real Madrid)', 'Develops combining 2v2 on the flank to deliver crosses for three runners.', 'Half pitch in 3 zones; a mini goal at the end of each side zone; 2v2 in the middle (10 and 9 v two centre backs), 2v2 in each side zone (full back and winger v full back and winger); keeper and coach with balls.', 'The coach feeds a side player who has lost his marker; whites work the ball forward to the end of the zone and cross with 1-2 touches for the three players running in; defenders cannot follow attackers out of the zone.', 'Opposite-side defenders stay out of the centre. If the 2 blue defenders win it in a side zone they have 6 seconds to score in the mini goal.', 'Variation (Practice 6): side players pass into the striker, who sets first time to 10, who switches into space behind for the far wide forward (7) to cross for the 3 runners.', NULL, '6v6 + GK', 13, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Quick finishing 7v5 around the box', 'finishing', 'overload', 'in_possession', 56, 56, 'Intelligent Positioning in the Box: Practice 1', 'Mourinho (Real Madrid)', 'Fast attacking combinations and finishing from inside and outside the penalty area.', 'Area twice the size of the box with a full goal and keeper at each end; whites in a 2-3-1 shape, blues in a 2-2; a 3v2 in one half (central mids) and a 1v2 striker v centre backs in the other; two white wide forwards run the flanks outside the main area.', 'Play starts from the white keeper; whites combine quickly, using the wide forwards, to score inside or outside the box; blues can counter to the other goal.', 'Whites 1-2 touches; wide forwards cannot enter the main area; a blue goal counts double.', NULL, 'High tempo; quick decisions; shoot from in and outside the box; accurate short crosses; react fast to transitions.', '7v5 (+2 GK)', 14, 14, 'double penalty area', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Winning the second ball with quick finishing', 'transition', 'opposed', 'to_defend', 57, 57, 'Intelligent Positioning in the Box: Practice 2', 'Mourinho (Real Madrid)', 'Combine and finish around the box while winning second balls and reacting to losing the ball high up.', 'Final third split into 2 zones; full goal with keeper at one end and 2 mini goals at the other; whites in a 2-3-1, blues in a 4-1; coach with balls by the mini goals.', 'Whites attack the full goal from inside and outside the box, always keeping 2 players back in their own half for the second ball and defensive cover; blues who win it try to score in the mini goals.', 'Blues have 5-6 touches maximum to score; coach restarts with a new ball to whites.', NULL, 'No side players now, so dribble and beat your man 1v1; close down the ball carrier at once after losing it; the 2 central mids win the second ball and shoot from range.', '6v5 (+GK)', 12, 12, 'final third of the pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Win the ball back in a dynamic game', 'transition', 'opposed', 'to_defend', 58, 58, 'Intelligent Positioning in the Box: Practice 3', 'Mourinho (Real Madrid)', 'Counter-press immediately after losing the ball while attacking the box.', 'The 2 zones joined into one big area; full goal with keeper at one end, 3 mini goals at the other (one central, two at the sides angled to face the blues); blues gain an extra central midfielder.', 'Whites combine to score; when they lose it they must close the blues down immediately to stop them scoring in the mini goals.', 'Blue goal in a side mini goal = 1 point, central mini goal = 2 points; coach feeds a new ball to whites when it goes out.', NULL, NULL, '6v6 (+GK)', 13, 13, 'final third of the pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Crossing with advanced full backs, 3 zones', 'finishing', 'overload', 'in_possession', 60, 60, 'Full Backs in Advanced Positions: Practice 1', 'Mourinho (Real Madrid)', 'Attacking and defending in the box from crosses delivered by overlapping full backs.', 'Final third split into 3 zones (2 side channels); full goal with keeper at one end, 2 mini goals at the other; the 2 white full backs sit in the side zones, blues in a 4-2.', 'Whites attack to score from in or outside the box, using the full backs in the channels to cross; if blues win it they try to score in the mini goals.', 'Full backs stay in the side zones and are limited to 2 touches; no blue defenders (or just one at a time) in the side zones; blues have 5 touches maximum to score; coach restarts.', 'Practice 2 version: side zones shortened to the length of the box with 4 mini goals.', 'Width on the flank gives quality crosses; decision making, pass weight and timing of runs into the box; communicate; react fast to losing the ball and win the second ball.', '8v6 (+GK)', 15, 15, 'final third of the pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Crossing with advanced full backs, 4 mini goals', 'finishing', 'overload', 'in_possession', 61, 61, 'Full Backs in Advanced Positions: Practice 2', 'Mourinho (Real Madrid)', 'Crossing and finishing from full backs high and wide, with a counter threat on breakdown.', 'Same area but the 2 side zones are cut down to the length of the penalty area; 4 mini goals at the far end; the 2 white full backs work in the wide strips next to the box.', 'Whites build and cross into the box; when their attack breaks down or the ball is cleared, blues aim for any of the 4 mini goals while whites switch to defending.', 'Blues may not enter the side zones; coach restarts with a new ball to whites.', NULL, NULL, '8v6 (+GK)', 15, 15, 'final third of the pitch', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Width and switching play 6v6+2 SSG', 'small_sided_game', 'overload', 'in_possession', 67, 67, 'Switching Play to Change the Point of Attack: Practice 1', 'Mourinho (Real Madrid)', 'Keep possession and use the full width to switch the point of attack.', '50 x 40 yard area in 3 zones: central zone 40 x 40 and two 40 x 5 side strips; 3 mini goals at each end; 6v6 in the middle (both 2-3-1) with a neutral in each side strip.', 'Teams keep the ball and switch play to the wide neutrals; 8 passes earns 1 point; scoring in any of the 3 mini goals earns 2; a goal straight from a neutral''s pass earns 3.', 'Only neutrals in the side strips and they cannot go central.', '1) Neutrals can score. 2) Neutrals cannot score. 3) Unlimited touches, 1-touch finish. 4) 2-3 touches for all, 1-touch finish.', 'Change direction quickly by switching to the wide neutrals; low-risk on the ball so possession is kept for the switch.', '6v6 +2 neutrals', 14, 14, '50 x 40 yards', 45.7, 36.6, NULL, true, false, true, NULL, 280),
  ('Switching play with advanced full backs SSG (1)', 'small_sided_game', 'overload', 'in_possession', 68, 68, 'Switching Play to Change the Point of Attack: Practice 2', 'Mourinho (Real Madrid)', 'Switch play to advanced full backs and attack crosses into the box.', 'Half pitch in 3 zones; one team defends a full goal with keeper, the other defends 2 mini goals; 6v6 in the centre (whites 2-3-1, blues 4-2 + GK); 2 full backs in the side zones play for the team in possession.', 'Whites circulate and switch to the full backs, then attack crosses with timed runs into the box; blues who win it can score in either mini goal; teams swap roles and the coach keeps score.', 'Goal direct from a full-back pass counts double; blue goal in a mini goal counts double; central players cannot enter the side zones.', '1) Full backs can come inside and score. 2) Full backs can come inside but not score. 3) Full backs always outside. 4) Unlimited touches, 1-touch finish. 5) 2-3 touches, 1-touch finish.', 'High tempo passing; good starting spots around the box and timed runs to different areas; both teams ready for transition.', '6v6 (+2 full backs, +GK)', 15, 15, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Switching play with advanced full backs SSG (2)', 'small_sided_game', 'overload', 'in_possession', 69, 69, 'Switching Play to Change the Point of Attack: Practice 3', 'Mourinho (Real Madrid)', 'Switch play through wide neutrals in a two-goal game.', 'Same half-pitch zones but both teams now defend a full size goal with keeper; neutrals in each side zone; both teams 2-3-1 in possession, 4-2 out of it.', 'Both teams keep the ball, use the 2 wide neutrals to switch and create crosses or finishes.', NULL, '1) Neutrals can come in and score. 2) Neutrals can come in but not score. 3) Neutrals always outside. 4) Unlimited touches, 1-touch finish. 5) 2-3 touches, 1-touch finish.', NULL, '7v7 (+2 neutrals, GKs)', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Width and creating space around the box', 'phase_of_play', 'overload', 'in_possession', 70, 70, 'Switching Play to Change the Point of Attack: Practice 4', 'Mourinho (Real Madrid)', 'Break down a compact ball-oriented defence crowding the centre.', '5 cones about 10-15 yards outside the box mark 3 zones; 3 mini goals beyond the area (3 yards from the side zones, 5 from the centre); whites 2-3-1 attack a full goal and keeper, blues defend in a 4-1; a coach with balls on each side.', 'Coach passes to a white player; whites combine to score; if blues win it they counter into one of the 3 mini goals; after a goal or ball out, the coach on the other side feeds a new ball to whites.', NULL, NULL, 'Dribble forward to draw defenders then release into space; if the defence stays balanced, switch quickly to the weak side.', '6v5 (+GK)', 12, 12, 'edge of box to 15 yards out', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Passing in behind in a 9 zone SSG', 'small_sided_game', 'overload', 'in_possession', 73, 73, 'Timed Runs Between Full Back and Centre Back: Practice 1', 'Mourinho (Real Madrid)', 'Attack behind a deep back line with diagonal runs between full back and centre back.', '60 x 55 yard area split into 9 zones: central Area 1 (35 x 40), Area 2s at the sides (35 x 7.5), Area 3 corners (12.5 x 7.5), Area 4 end zones (12.5 x 40); full goals with keepers; 6v6 in Area 1 and a neutral in each Area 2.', 'Team in possession plays with the neutrals, who stay in Area 2 (one defender may go in there at a time), and makes diagonal cutting runs into Areas 3 and 4 to create chances.', NULL, '1) No marking in Area 3 but attackers 2 touches. 2) Marking allowed. 3) Unlimited touches in Area 1, limited elsewhere. 4) 2-3 touches maximum, 1-touch finish.', 'Open body shape on the half turn; right angles and distances of support; time the pass and run together; quality finishing.', '7v7 (+2 neutrals)', 16, 16, '60 x 55 yards', 54.8, 50.3, NULL, true, true, true, NULL, 320),
  ('Diagonal runs in behind SSG', 'small_sided_game', 'overload', 'in_possession', 74, 74, 'Timed Runs Between Full Back and Centre Back: Practice 2', 'Mourinho (Real Madrid)', 'Exploit space in behind with diagonal runs from the flanks.', 'Same pitch with Areas 3 and 4 merged into end zones; the 2 neutrals now play in the central zone; goals with keepers at both ends.', 'Each team may put one player in each side zone at a time; teams combine and make diagonal runs into the end zones where defenders can mark them.', NULL, '1) Neutrals can score. 2) Neutrals cannot score. 3) Unlimited touches (neutrals 2), 1-touch finish. 4) 2-3 touches (neutrals 1), 1-touch finish.', NULL, '7v7 (+2 neutrals)', 16, 16, '60 x 55 yards', 54.8, 50.3, NULL, true, true, true, NULL, 330),
  ('Timing runs between deep defenders 8v8', 'phase_of_play', 'opposed', 'in_possession', 75, 75, 'Timed Runs Between Full Back and Centre Back: Practice 3', 'Mourinho (Real Madrid)', 'Attack behind a deep line with runs between full back and centre back.', 'Half pitch with a central zone and 2 side channels; central zone split into 2 grids at the edge of the box; 2 mini goals on halfway; whites 2-2-3-1 (incl. full backs) attack a full goal and keeper, blues defend in a 4-4.', 'Whites work the ball wide to create a 2v1 in the side channels (only 1 blue may enter at a time) and time runs in between defenders; blues who win it score in the mini goals for double; whites must transition quickly when they lose it.', NULL, '1) Whites limited touches centrally, unlimited at the sides. 2) Unlimited centrally, 2-3 touches at the sides. 3) Limited touches or time for all to finish. 4) Everyone unlimited.', NULL, '8v8 (+GK)', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('6v6+2 passing into the goal zone', 'positional_game', 'overload', 'in_possession', 77, 77, 'Attacking in Behind Through the Centre: Practice 1', 'Mourinho (Real Madrid)', 'Quality and timing of the run and final pass behind a defensive line.', '45 x 40 yard area in 3 zones: central 35 x 40 and two 5 x 40 goal zones; 6v6 with 2 neutrals acting as central mids for the team in possession (4-2-3-1 shape).', 'The team in possession uses quick combinations to play into a goal zone behind the defence; a point is scored when a teammate receives in the goal zone under control.', NULL, NULL, 'Use the extra players to make runs in behind often; pass speed and quality, decisions, support angles, creative combinations.', '6v6 +2 neutrals', 14, 14, '45 x 40 yards', 41.1, 36.6, NULL, false, false, true, NULL, 350),
  ('6v6+2 support play in 1v1 zones', 'small_sided_game', 'overload', 'in_possession', 78, 78, 'Attacking in Behind Through the Centre: Practice 2', 'Mourinho (Real Madrid)', 'Win 1v1s and support play to break through, then finish.', 'Playing area split into 6 grids of about 10 x 10 yards, a 1v1 in each; 2 free neutrals; goal zones at each end with full goals and keepers.', 'Players stay in their own grid unless running into the goal zone; neutrals move anywhere to create 2v1 or 3v1 overloads, playing 1-2s and third-man runs to progress.', 'Unlimited touches for normal players, 1-2 touches for neutrals.', NULL, 'Shield the ball in 1v1s and get your body between opponent and ball; neutrals drive the 1-2s and third-man runs.', '7v7 (+2 neutrals)', 16, 16, '6 grids of about 10 x 10 yards plus goal zones', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('7v7+2 runs in behind and finishing', 'small_sided_game', 'overload', 'in_possession', 79, 79, 'Attacking in Behind Through the Centre: Practice 3', 'Mourinho (Real Madrid)', 'Quality and timing of runs and final passes in behind, then finishing.', '75 x 40 yard area: central zone 35 x 40 and two 20 x 40 end zones with full goals and keepers; 2 neutrals with the team in possession (2-2-3-1).', 'After a minimum number of passes (coach decides) the team plays a final ball into the end zone for a runner to finish.', NULL, '1) No minimum passes before the final ball. 2) No defenders in end zones, attackers 2 touches. 3) 1 defender and 2 attackers in the end zone. 4) Attackers 2 touches, 1-touch finish. 5) Everyone may enter once the ball is played in.', 'Keep the ball and use the overload first; once the passes are done, go forward quickly; rhythm and timing of runs.', '7v7 (+2 neutrals)', 16, 16, '75 x 40 yards', 68.5, 36.6, NULL, true, true, true, NULL, 370),
  ('Receiving in behind a deep line 9v9', 'conditioned_game', 'opposed', 'in_possession', 80, 80, 'Attacking in Behind Through the Centre: Practice 4', 'Mourinho (Real Madrid)', 'Attack behind a deep line with the right run and final pass.', 'Half a full pitch: central zone 65 x 30, end zones 65 x 18 and 65 x 8, full goals at each end; the small zone is a safe zone for whites (reds cannot enter); whites 2-2-3-1, reds 4-4.', 'Whites look to play into the final zone for a runner; defenders cannot drop in there before the ball; reds who win it can score anywhere.', NULL, '1) Reds may intercept in the centre but not tackle. 2) No defenders in the final zone, attacker 2 touches. 3) 1 defender and 2 attackers in the final zone. 4) Attackers 2 touches, 1-touch finish. 5) One fewer defender than attackers in the final zone, 2 touches then 1-touch finish.', NULL, '9v9', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Combinations and finishing with offside rule', 'combination', 'overload', 'in_possession', 82, 82, 'Timing Runs in Behind to be Onside: Practice 1', 'Mourinho (Real Madrid)', 'Quick combinations in and around the box while timing runs to stay onside.', 'Area twice the penalty box split into 2 zones with an offside line; 4 white attackers (from the 4-2-3-1) v 4 defenders and a keeper; 2 neutrals at the end without a goal act as the central mids.', 'Whites combine to work an opening inside the box and score past the keeper; if defenders win it they keep the ball as long as possible with the 2 neutrals.', '1-2 touches; offside applies.', NULL, 'Good decisions, creativity and quick transitions; coordinate runs and passes to attack different spaces; high tempo, quick forward passing.', '4v4 +2 neutrals (+GK)', 11, 11, 'double penalty area', NULL, NULL, NULL, true, true, true, NULL, 390),
  ('6v5 attacking with the offside rule', 'phase_of_play', 'overload', 'in_possession', 83, 84, 'Timing Runs in Behind to be Onside: Practice 2', 'Mourinho (Real Madrid)', 'Timed runs and quick finishing against a back line with offside.', 'Same area with an offside line; whites now have 2 central mids, blues 1 central mid; 2 mini goals for blues at the coach''s end; full goal and keeper for whites to attack.', 'Whites combine and time runs to finish; if blues win the ball they try to score in the 2 mini goals.', '1-2 touches; offside applies.', 'Practice 3 variation: blues switch to a 2-2-1 (no full backs: 2 centre backs, 2 central mids, 1 attacking mid), same rules.', NULL, '6v5 (+GK)', 12, 12, 'double penalty area', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Offside rule attacking in a SSG', 'small_sided_game', 'overload', 'in_possession', 85, 85, 'Timing Runs in Behind to be Onside: Practice 4', 'Mourinho (Real Madrid)', 'Time runs to stay onside and finish in a two-goal game.', 'Same area but now a full size goal with keeper at both ends; offside line marked.', 'Whites attack with combinations and timed runs; blues counter to the other full goal.', '1-2 touches; offside applies.', 'Can be played with the blue 2-2-1 formation from the previous practice.', NULL, '6v5 (+2 GK)', 13, 13, 'double penalty area', NULL, NULL, NULL, true, true, true, NULL, 410),
  ('Flank space and timed runs, unopposed', 'combination', 'unopposed', 'in_possession', 91, 91, 'Creating Space for 1v1 Situations on the Flank: Practice 1', 'Mourinho (Real Madrid)', 'Attack down the flank and exploit 1v1s with the wide forwards.', 'Three quarters of a pitch with 3 zones on each side and 1 central zone; a mannequin in each middle side zone and 4 mannequins centrally; centre mid, 2 full backs, 2 wide forwards, attacking mid and striker plus keeper.', 'The centre mid passes to a full back, who takes 2 touches and plays into space for the wide forward after his check-away; the wide forward drives at speed toward the box and crosses low for runners.', 'Full back 2 touches.', NULL, 'Mix pass types (feet, space, short, long, curved) with correct weight; check away before receiving; quality crossing and 1-touch finishing.', '7 attackers + GK', 8, 8, 'three quarters of a pitch', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Flank space and timed runs, opposed', 'phase_of_play', 'opposed', 'in_possession', 92, 94, 'Creating Space for 1v1 Situations on the Flank: Practice 2', 'Mourinho (Real Madrid)', 'Create and use a 1v1 on the flank against live opponents.', 'Same zones with 7 active opponents; a ''marked area'' on each side; 3v4 in the central zone.', 'After the first pass, the opponent''s wide midfielder steps out to press the full back but cannot leave the marked area, which the white full back may not enter; near the box only the red full back and white wide forward play (1v1); central players can attack or defend the cross.', 'Far-side full back may not enter the box.', 'Practice 5: one central player (attacking mid or striker) may enter the side zone to combine with full back and wide forward, and one red may follow him.', 'Timing and communication in side zones; check away from markers; runners spread to near post, far post etc.', '7v7 (+GK)', 15, 15, 'three quarters of a pitch', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('2v2 on the flanks with crossing', 'phase_of_play', 'opposed', 'in_possession', 93, 93, 'Creating Space for 1v1 Situations on the Flank: Practice 3', 'Mourinho (Real Madrid)', 'Full back and wide forward combine 2v2 to cross for finishers.', 'Same set-up as the opposed practice; full backs can now enter the marked middle zone but not the zone nearest the box.', 'Full back and wide forward combine against their opponents to free the cross; central runners attack the box.', NULL, 'Practice 4: wide forwards may also pass and combine with the attacking mid in the central zone, but nobody may leave their zone.', NULL, '7v7 (+GK)', 15, 15, 'three quarters of a pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Forward runs and through balls zonal game', 'small_sided_game', 'overload', 'in_possession', 98, 98, 'Midfield Forward Runs in Behind the Defence: Practice 1', 'Mourinho (Real Madrid)', 'Final pass and diagonal runs between full back and centre back against a middle line.', '60 x 45 yard area: 3 central zones (middle 30 x 30, sides 7.5 x 30) and 2 end zones of 15 x 30 with goals and keepers; 6v6 in the middle (both 2-3-1) with a neutral in each side zone.', 'Team in possession uses the side neutrals (who stay in their zone) and plays through balls for runners into the final zone; defenders cannot enter it until the ball is played in.', NULL, '1) No defenders in side zones. 2) One defender at a time in the side zone, fully active. 3) Unlimited entry to the side zones.', NULL, '7v7 (+2 neutrals)', 16, 16, '60 x 45 yards', 54.8, 41.1, NULL, true, true, true, NULL, 450),
  ('Timing runs between defenders 4 zone game', 'phase_of_play', 'overload', 'in_possession', 99, 99, 'Midfield Forward Runs in Behind the Defence: Practice 2', 'Mourinho (Real Madrid)', 'Use the overload out wide and diagonal runs between full back and centre back.', '2 mini goals 15 yards past halfway; central zone 44 x 44 and side zones 40 x 20; 6v6 centrally (whites 2-3-1, reds 4-2) plus a white full back in each side zone; reds can move into any zone; full goal and keeper.', 'Whites exploit the wide overload with diagonal runs as the red full back and centre back are pulled apart, aiming to get into the final zone and score; reds who win it score in a mini goal.', 'Reds 5-6 passes or 10-15 seconds to score.', '1) Unlimited centrally, full back 2 touches. 2) 3 touches centrally, full back 2. 3) 2 touches max in the final zone. 4) 2 touches in the final zone, 1-touch finish. 5) 1 touch in the final zone.', NULL, '8v6 (+GK)', 15, 15, '44 x 44 yard centre plus 40 x 20 side zones', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Timing runs between defenders 9v9', 'conditioned_game', 'opposed', 'in_possession', 100, 100, 'Midfield Forward Runs in Behind the Defence: Practice 3', 'Mourinho (Real Madrid)', 'Time runs between defenders against a middle line with switches of play.', 'Adds a safe zone with a keeper for whites across the full width up to the edge of the box; full goals at each end; whites 2-2-3-1, reds 4-4.', 'Whites build from the safe zone and play in behind; switch side zone to side zone = 1 point, 8 passes in a row = 2, goal = 3; only certain players may enter side zones; defenders cannot enter the final zone before the ball; restarts from the goalkeeper.', 'Reds may not enter the white safe zone.', '1) Unlimited centrally, 2 touches in the final zone. 2) 3 touches centrally, 2 in the final zone. 3) Key players unlimited, others limited. 4) Any of these with 1-touch finishing.', NULL, '9v9', 18, 18, 'half pitch plus safe zone', NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Timing runs in an 11v11 zonal practice', 'conditioned_game', 'opposed', 'in_possession', 101, 101, 'Midfield Forward Runs in Behind the Defence: Practice 4', 'Mourinho (Real Madrid)', 'Timed runs in behind in a full-pitch position specific game.', 'Full pitch in zones; whites add 2 centre backs and reds add 2 attackers to the previous set-up.', 'With whites in their low zone only red 9 and 10 may press there; once the ball enters the middle zone the other reds press, and white 4 and 5 and red 9 and 10 stay out of it; whites aim to play in behind and score; if reds win it all may attack the white low zone.', 'Reds have limited touches or time to finish.', 'Whites: 1) Unlimited centrally, 2 in the final zone. 2) Limited centrally, 2 in the final zone. 3) Key players unlimited. 4) 1-touch finishing. 5) 1 touch for all in the final zone.', NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('6v6+2 end zone final ball game', 'positional_game', 'overload', 'in_possession', 105, 105, 'Through Balls from the Flank into the Centre: Practice 1', 'Mourinho (Real Madrid)', 'Create chances in behind a middle line with the final ball into an end zone.', '60 x 45 yard area in 5 zones: middle 30 x 30, side zones 7.5 x 30 and end zones 15 x 30; 6v6 both in a 2-3-1 with a neutral full back in each side zone.', 'Team in possession switches to the side neutrals and plays a final ball into the end zone for a runner; defenders cannot enter the end zones before the ball arrives.', NULL, '1) No defenders in side zones. 2) One active defender in a side zone at a time. 3) Unlimited touches, neutrals 2 or 1-2. 4) A 3rd neutral in the centre. 5) Centre 1 touch, side neutrals 2.', 'Switch to the side neutrals to use the extra width; inside players make opposite runs into end zones; time run and pass.', '6v6 +2 neutrals', 14, 14, '60 x 45 yards', 54.8, 41.1, NULL, false, false, true, NULL, 490),
  ('Diagonal through balls from wide areas', 'phase_of_play', 'overload', 'in_possession', 106, 107, 'Through Balls from the Flank into the Centre: Practice 2', 'Mourinho (Real Madrid)', 'Quick combinations to play diagonal balls in behind from wide areas.', '4 mini goals 15 yards past halfway; 2 zones split by cones 10 yards from the box, main zone 40 x 65; whites 2-2-3-1 with 3 neutrals (2 wide, 1 central) in possession only; blues 4-4 with keeper on a full goal.', 'Whites combine to get into the final zone and in behind; blue defenders cannot enter the end zone before the ball; blues who win it score double in the mini goals.', NULL, 'Central zone rules: 1) Whites unlimited, neutrals 2 (or all 2-3). 2) Whites and central neutral 2-3, side neutrals 1. 3) Defenders, striker and neutrals 2, AM and wide forwards unlimited. 4) Final zone 3 to 2 to 1 touch for key players. Practice 3: just 2 neutrals, both in the main zone.', NULL, '8v8 (+GK, +3 neutrals)', 20, 20, '40 x 65 yard main zone', 36.6, 59.4, NULL, true, true, true, NULL, 500),
  ('Passing behind a middle line 9v9', 'conditioned_game', 'opposed', 'in_possession', 107, 107, 'Through Balls from the Flank into the Centre: Practice 4', 'Mourinho (Real Madrid)', 'Play in behind a middle defensive line with a quick counter threat.', 'Mini goals removed; safe zone for whites up to the edge of the box; full goals at both ends.', 'Reds start defending when the ball enters the central zone and cannot enter the safe zone; whites play through and in behind; reds who win it have 10 seconds to score.', 'Reds 10 seconds to score.', NULL, NULL, '9v9', 18, 18, 'half to three quarters pitch', NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Switch play and through balls, 5 zones', 'phase_of_play', 'opposed', 'in_possession', 109, 109, 'Practice 1 (Long Switch of Play to Create Space for a Final Ball)', 'Mourinho (Real Madrid)', 'Builds combinations that create chances in behind a middle-height defensive line, by switching to a full back for a 1v1 on the flank.', 'Full pitch; middle third split into 3 zones, centre zone 40x40 yards with two side zones. Whites in 4-2-3-1 v blues in 5-4-1, each with a GK.', 'White centre backs stay outside the central zone, full backs stay in the side zones, midfield and front players work in the central zone until the ball reaches the end zone. Whites keep the ball, then switch it wide to a full back who either passes into space behind the back three for a supporting runner, or dribbles inside to unbalance the line and slips a shorter pass in behind.', 'Only the blue full backs may enter the side zones; the blue striker stays outside the central zone with the two white centre backs.', NULL, NULL, '11v11 (4-2-3-1 v 5-4-1)', 22, 22, 'Full pitch; central zone 40 x 40 yards', NULL, NULL, NULL, true, true, true, NULL, 520),
  ('4 zone possession game with neutrals', 'possession', 'overload', 'in_possession', 114, 114, 'Session: Practice 1 (Playing the Ball in Behind a High Defensive Line)', 'Mourinho (Real Madrid)', 'Keeping the ball under heavy pressure in tight space and time.', '20x20 yard square split into four 10x10 grids with a 2v2 in each; 4 neutrals, one on each side of the square, who can slide along their side but never enter.', 'Team in possession uses the outside neutrals to keep the ball and move it between grids.', '8 passes or 10 seconds of possession = 1 point; moving the ball through all four grids without losing it = 2 points. Rule sets: unlimited touches for grid players with neutrals on 1-2 touches, or everyone on 1-2 touches.', NULL, 'Open body on the half turn to see the next pass; shield the ball in the 1v1/2v2s; quality and speed of pass, good angles and distances of support.', '8v8 (+4 neutrals)', 20, 20, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 530),
  ('Position specific 7v7 plus 1 possession', 'possession', 'overload', 'in_possession', 115, 116, 'Session: Practice 2', 'Mourinho (Real Madrid)', 'Possession under high pressure with players in their match positions.', '20x25 yard area of 7 grids: central 12x12 grid with a 2x12 grid each end, plus four 16x5 outside channels. Centre has 3v3 + 1 neutral; channels hold 1v1 wide players; each end zone a centre back with the opposing striker in front.', 'Teams keep the ball by moving it through the central grid, the wide channels and back to the centre backs. Centre backs may step into the striker''s zone; strikers may only press the centre back from their own zone to block or intercept.', '6 passes or 8 seconds = 1 point; ball through all the grids = 2 points. Touches: centre backs and wide players 2-3 (or 2), strikers and neutral 1, inside players unlimited (or 2-3).', NULL, 'Inside players always look to switch play to the outside channels; wide players check away before receiving; choose feet or space; win the 1v1s; sharp support angles.', '7v7 (+1 neutral)', 15, 15, '20 x 25 yards', 22.9, 18.3, NULL, false, false, false, NULL, 540),
  ('Build up through the lines v high press', 'positional_game', 'opposed', 'in_possession', 117, 118, 'Session: Practice 3', 'Mourinho (Real Madrid)', 'Playing out from the back through the lines against a high press, with quick support.', '45x35 yard area with one goal. Multi-colour team: GK, 4 defenders (white), 2 centre mids (blue), 4 front players (yellow) in 4-2-3-1 v 10 reds pressing high.', 'The ball goes white to blue and back to a supporting white, then white to yellow and back to a supporting blue, then on to yellow, working through the lines and back. If reds win it they must score within 5-6 passes, forcing a quick transition to defend.', '6-8 passes or 8-10 seconds of possession = 1 point; ball from GK through white, blue, yellow and all the way back to the GK = 2 points. Touch variations: whites 2-3, blues 1 or unlimited, yellows unlimited or 2-3; or all unlimited.', NULL, 'Half-turn body shape; decide when to hold, play first time or dribble; check away to receive; vertical passes skip defenders; switch to use full width; be alert to the counter and recover behind the ball.', '11v10', 21, 21, '45 x 35 yards', 41.1, 32.0, NULL, true, true, true, NULL, 550),
  ('Play in behind a high line, 11v11', 'conditioned_game', 'opposed', 'in_possession', 119, 119, 'Session: Practice 4', 'Mourinho (Real Madrid)', 'Attacking the space behind an opponent that holds a high defensive line.', 'Full pitch in 3 zones: a safe zone for the whites at the back, a central zone where reds hold a high line, and a final attacking zone.', 'Whites build from the back under high pressure and look to break it with passes in behind the line; reds may not enter the safe zone and can only enter the attacking zone once the ball has gone in there. Reds that win the ball have 8-10 seconds or 6-8 passes to score.', 'Whites must complete 6-8 passes before playing into the final zone.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Breaking pressure possession, switch grids', 'possession', 'overload', 'in_possession', 121, 121, 'Session: Practice 1 (Building Up Play against Opponents who Press High)', 'Mourinho (Real Madrid)', 'Keeping the ball under intense pressure and changing the direction of attack, with quick movement and support.', '50x40 yard area split into 2 grids. Two teams of 7 plus 2 neutrals. In the active grid 5 players sit on the sides (2 centre backs at the back, left and right backs, one on the middle line) with the 2 neutrals inside, against all 7 opponents; 2 more teammates wait at the far end of the other grid.', 'The team in possession makes 5-6 passes and then switches to the other grid; the two wide players and neutrals move across to support, the centre backs and middle player stay. Possession restarts in the other grid; if the defenders win it, roles reverse.', 'Target 5-6 passes before the switch.', 'Must keep the ball 10 seconds before switching; on a switch the middle player swaps with one of the bottom players who sprints up.', NULL, '7v7 (+2 neutrals)', 16, 16, '50 x 40 yards', 45.7, 36.6, NULL, false, false, true, NULL, 570),
  ('Dynamic transitional possession in 4-2-3-1', 'possession', 'overload', 'in_possession', 122, 122, 'Session: Practice 2', 'Mourinho (Real Madrid)', 'Possession under heavy pressure and switching the point of attack, with quick reaction to transitions.', '80x40 yard area of two 40x40 halves. Left half 6v6 + 2 neutrals (the outside neutral acts as a keeper, the inside one as an extra man); 3 whites and a neutral wait in the other half.', 'Keep the ball in one half for 6-8 passes, then switch to the 3 players or neutral in the other half; 3 whites and the inside neutral follow, 3 reds also cross, recreating 6v6+2. If reds win it they take on the same task.', 'Unlimited touches for regular players with neutrals limited, or all players limited.', NULL, 'React fast to losing the ball; defenders coordinate pressure to stop the switch; pass quality, decisions, angles and distances of support.', '9v9 (+3 neutrals)', 21, 21, '80 x 40 yards', 73.1, 36.6, NULL, false, false, true, NULL, 580),
  ('Play through the lines, 3 zone SSG', 'small_sided_game', 'opposed', 'in_possession', 123, 123, 'Session: Practice 3', 'Mourinho (Real Madrid)', 'Building up through the lines under pressure and finishing quickly.', '80x40 yard area with a goal each end: two 36x40 end zones and a 12x40 central zone. Low zone: GK + 7 whites (4-2-1 type with AM along the line) v 6 reds; middle zone 1 red along the line; high zone 2 red defenders + GK v 2 white attackers.', 'Whites keep the ball in the low zone for 6-8 passes, then find one of the two front players who must lay it back; 3 whites then move up for a 5v3 and have 5-6 touches or 6-8 seconds to finish. Reds that win it high or in the middle try to score; win it in the low zone and they keep it and roles swap, restarting from the other end.', 'Touch rules: unlimited in low and middle zones with limited touches high; unlimited low with limited middle and high; or limited everywhere.', NULL, NULL, '9v9', 18, 18, '80 x 40 yards', 73.1, 36.6, NULL, true, true, true, NULL, 590),
  ('Break the press high up, 3 zone game', 'conditioned_game', 'opposed', 'in_possession', 124, 125, 'Session: Practice 4 (and Practice 5)', 'Mourinho (Real Madrid)', 'Escaping a high press from the low zone and exploiting an overload in the middle to score.', 'Full pitch in low, middle and high zones. Low zone: 7 white outfield players (4-2-1) v 7 reds pressing; middle zone: 2 white attackers v 3 red defenders.', 'Whites play out and get a player into the middle zone with a 1-2, making 3v3, or 4v3 when one extra teammate joins, then attack quickly to create a chance and score.', 'Touch options: unlimited high and middle with limited low; unlimited high with limited middle and low; or limited everywhere.', 'Practice 5: 11v11 with 3v3 in the middle zone at the start, so the attack becomes 5v3.', NULL, '10v11', 21, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Unopposed fast break attack', 'combination', 'unopposed', 'to_attack', 132, 132, 'Session: Practice 1 (Creating and Taking Advantage of 1v1 / 2v2 Situations)', 'Mourinho (Real Madrid)', 'Rehearsing fast break attacks that exploit 1v1 or 2v2 situations.', 'Full pitch with cones and mannequins (one in midfield, two as centre backs in the attacking half). Player 6 starts in the penalty area, wide forwards on each flank, 10 in front of the area, 9 up front.', '6 passes to 10, who takes a directional first touch, dribbles forward and does a 360 turn or feint at the mannequin. 11 makes a diagonal opposite run, receives from 10 and drives on; 9 checks away and runs into the space behind or between the two mannequins, receives from 11 and shoots. Repeat from the other side.', NULL, NULL, '10 checks away before receiving; close fast control with a change of direction when dribbling; accurate, well-weighted passes timed with the runs.', NULL, NULL, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 610),
  ('Opposed fast break with 1v1 and 2v2', 'transition', 'opposed', 'to_attack', 133, 133, 'Session: Practice 2', 'Mourinho (Real Madrid)', 'Defending a cross, then breaking at speed through 1v1 and 2v2 duels.', 'Full pitch 11v11 with central channels marked by mini goals; balls with red wide players on both flanks; 4v4 in the box.', 'A red wide player crosses while the white full back presses; whites defend the box and clear to 6, who feeds 10 for a 1v1 against the red centre midfielder (red scores in a mini goal if he wins it). If 10 beats him he plays into the next zone for 7 or 11 on a diagonal run, and they attack 2v2 with the striker.', 'Attack must be finished within 12 seconds of 6 receiving the clearance.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 620),
  ('Transition and support, 3 zone dynamic game', 'transition', 'overload', 'to_attack', 135, 136, 'Session: Practice 1 (Quick Counter Attacking from the Low Zone)', 'Mourinho (Real Madrid)', 'Transitions from defence to attack in the low zone and using 1v1 or 2v2 situations.', '60x40 yard area: central zone 10x40, two outer zones 25x40. Neutral (blue) players at each end. In the starting zone 8 red attackers (4 mids, 2 attackers inside, 2 full backs on the sides) v 6 white defenders; in the centre a white 10 v a red; in the far zone white 9 v red 5 with white side forwards on the touchlines.', 'Reds keep the ball for points (6-8 passes = 1 point). Whites try to win it and pass quickly to 10 in the central zone, with one player joining to support for a return pass, then repeat into the end zone with the striker and side players. Once in the end zone the roles of the two teams switch and play continues.', 'Team going from defence to attack has 1-2 touches in the first two zones and unlimited in the final zone (side players and neutrals 1-2 touches).', NULL, 'Ball-oriented pressing to win it back; cover and shifting between defenders; correct distances; in transition be aware, support fast and play at high tempo.', '8v8 (+2 neutrals)', 18, 18, '60 x 40 yards', 54.8, 36.6, NULL, false, false, true, NULL, 630),
  ('Transition and support with side players', 'transition', 'overload', 'to_attack', 137, 137, 'Session: Practice 2 (and Practice 3)', 'Mourinho (Real Madrid)', 'Quick counter attacks from the low zone on a full pitch with support from wide players.', 'Full pitch with GKs, zones as in the 3 zone dynamic game (central channel 8-10 yards); white wide forwards and red full backs start on the touchlines.', 'Same sequence as the 3 zone dynamic game, now finishing on goal.', 'The transitioning team has 8-10 seconds to finish the attack.', 'Practice 3 (11v11, 4 zones): the white wide forwards and red full backs play inside the pitch from the start.', NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 640),
  ('3 team counter attacking SSG', 'transition', 'overload', 'to_attack', 140, 141, 'Session: Practice 1 (Exploiting the Weak Side of the Opposition)', 'Mourinho (Real Madrid)', 'Counter attacking from the low zone and exploiting the opponent''s weak side.', '50x50 yard area in two halves with a goal and GK at each end. Two teams of 7 plus 6 neutrals in one half (some on the sides who may not come inside). Whites defend in a 4-2 with ball-oriented defence.', 'Reds attack with the neutrals'' help; when whites win it they break quickly into the other half, joined by neutrals there (who cannot score). After a goal or ball out, play restarts in the other half with roles and neutral team rotated.', 'Attack must finish within 8 seconds of winning the ball; limited touches inside, 1-2 touches for neutrals.', 'Variation (Practice 2): three teams; reds attack whites, whites win it and pass straight to blues who attack reds at the other end while whites become the neutrals; roles keep rotating.', 'Ball-oriented pressure to win it back; urgency moving the ball forward; several forward runs into the attacking half; use the full width to hit the weak side.', '7v7 (+6 neutrals)', 20, 21, '50 x 50 yards', 45.7, 45.7, NULL, true, true, true, NULL, 650),
  ('Play wide and switch in transition game', 'transition', 'overload', 'to_attack', 142, 142, 'Session: Practice 3', 'Mourinho (Real Madrid)', 'Counter attacking combinations from the low zone that go wide and finish with near and far post runs.', '50x50 yards in two halves, goal and GK each end. First half: GK + 6 whites v 9 reds (6 inside plus 3 outside: 2 on the sides, 1 on the middle line).', 'Reds use their overload to score. When whites win it they pass quickly to their player in the middle of the attacking half, who sets it back for a runner; the ball goes wide to a player near the touchline while the other two attack the near and far posts. Reds may enter the other half only once the ball is played there.', 'Attack finished within 8 seconds of winning it; if the ball goes out, restart in the other half with roles switched.', NULL, NULL, '10v10', 20, 20, '50 x 50 yards', 45.7, 45.7, NULL, true, true, true, NULL, 660),
  ('Weak side, 3 zone transition game', 'transition', 'overload', 'to_attack', 143, 143, 'Session: Practice 4', 'Mourinho (Real Madrid)', 'Low-zone transitions that exploit the opponent''s weak side.', '60x40 yard area in three 20x40 zones with a goal and GK each end. Low zone: whites in a 4-2 v 7 red attackers; middle zone whites have a 4v3 once they break.', 'Whites defend; on winning the ball they pass quickly into the middle zone and attack the weak side with a 4v3.', '10 seconds to finish from the moment the ball is won.', 'Allow one defender to track back from the low zone (4v3+1).', NULL, '10v10', 20, 20, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 670),
  ('Weak side transition game, full pitch', 'transition', 'overload', 'to_attack', 144, 144, 'Session: Practice 5', 'Mourinho (Real Madrid)', 'Low-zone transitions on a full pitch exploiting the weak side.', 'Full pitch in 3 zones. Low zone: GK + 8 defenders v 7 red attackers; middle zone: 2 whites v 3 reds.', 'When whites win it, at least 3 players from the low zone must push up to support the attack into the middle and high zones.', NULL, 'Let one more defender track back (5v3+1), or let everyone join the transition and enter all zones once the ball reaches the middle.', NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 680),
  ('Fast break and switch, 5 zone game', 'transition', 'overload', 'to_attack', 147, 148, 'Session: Practice 1 (Long Pass to Switch Play to the Weak Side on the Break)', 'Mourinho (Real Madrid)', 'Winning the ball in the low zone and switching quickly to the weak flank on the break.', 'Full pitch in zones: low zone GK + 6 whites (4-2) v 6 reds (4 mids, 2 attackers) + 2 red outside players; middle zone 2v2; high zone split into two side zones and the box.', 'Whites win it with ball-oriented defending and pass quickly into the middle, where players receive and play fast to the wide forward on the opposite flank. He dribbles forward until a centre back closes him, creating a 4v2+1 to finish.', '10 seconds to finish from winning the ball.', 'Variation (Practice 2): same set-up without the two red outside players in the low zone.', NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 690),
  ('Defend low, win it, break to mini goals', 'defending', 'opposed', 'out_of_possession', 151, 151, 'Session: Practice 1 (Creating and Exploiting Space on the Flanks), Group 1', 'Mourinho (Real Madrid)', 'Defensive organisation in the low zone followed by a quick break.', 'Half pitch with 4 mini goals near the halfway line. Whites: GK + 6 outfield in a 4-2; reds: 6 attackers.', 'Play starts from a red throw-in and whites press the ball at once. If they win it they must score in a mini goal.', 'Score within 6 seconds of winning the ball.', NULL, 'Ball-oriented pressure; cover and quick repositioning; correct distances; fast, aware, high-tempo transition.', '7v6 (GK + 6 v 6)', 13, 13, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 700),
  ('Fast combinations, support and finishing', 'transition', 'overload', 'to_attack', 152, 152, 'Session: Practice 2, Group 2', 'Mourinho (Real Madrid)', 'Quick transitions from defence to attack with combinations to score.', '30x25 yard area in 2 halves with a goal and GK, plus a pole. 4 defenders v 4 attackers (2 wide forwards, AM and striker).', 'A red right back dribbles up to white 11, leaves the ball at his feet and sprints round the pole to defend. 11 breaks with a 4v3+1 and the team combines to score. Defenders may not enter the attacking half until the ball goes in. Run from both sides.', NULL, NULL, 'Quick transition; creative combinations at high tempo; time runs in behind with the direction and weight of pass.', '4v4', 9, 9, '30 x 25 yards', 27.4, 22.9, NULL, true, true, true, NULL, 710),
  ('Fast combinations rotating transition game', 'transition', 'overload', 'to_attack', 153, 153, 'Session: Practice 3, Group 2 Variation', 'Mourinho (Real Madrid)', 'Repeated quick 4v3 attacks with rotating attackers and defenders.', '30x25 yard area with a goal and GK at both ends; extra white and red players waiting behind the goals.', 'GK plays wide and 4 whites attack 3 red defenders, who may not enter the other half until the ball does. Afterwards 3 of the whites swap with the 3 reds at the end; the remaining white joins 2 whites from the other end and these 3 defend, while the incoming reds plus one more attack the other way from the GK.', NULL, NULL, NULL, '4v3 rotating', 14, 16, '30 x 25 yards', 27.4, 22.9, NULL, true, true, true, NULL, 720),
  ('Counter attack 4v3, 3 zone game', 'transition', 'overload', 'to_attack', 154, 155, 'Session: Practice 4', 'Mourinho (Real Madrid)', 'Counter attacking from the low zone with an overload in the middle.', 'Full pitch in 3 zones. Low zone: 6 red outfield v 6 white defenders + GK (1-4-2); middle zone: 4v3.', 'Play starts from a red throw-in. When whites win it they pass into the middle zone within 4 seconds and launch a fast 4v3 attack.', 'Max 4 seconds to reach the middle zone; attack finished within 10-12 seconds.', 'Practice 5 (variation): same drill with 4v4 in the middle zone.', NULL, '11v10', 21, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 730),
  ('Support play, low zone transition SSG', 'transition', 'overload', 'to_attack', 158, 159, 'Session: Practice 1 (Breaking from the Low Zone: Delayed Pass)', 'Mourinho (Real Madrid)', 'Breaking from the low zone and unbalancing the defence with a dribble and a delayed final pass.', 'Full pitch in 3 zones. Low zone: GK + 5 white defenders (4-1) v 5 blue attackers (4-1 or 3-2); players up in the middle and high zones.', 'Blues try to score. When a white wins it he passes into the middle zone to a teammate dropping from the high zone and supports with a 1-2 (one blue follows), making a 5v5 in the far zone. Middle zone is unmarked.', NULL, 'Practice 2: 8 whites v 6 blues in the low zone and 2v4 in the middle; on winning it 3 whites move up (one blue may track) for a 5v4+1; teams swap ends and roles after each attack.', 'Use 1-2s to move up the pitch; dribble close up to the defensive line then release a delayed pass; time the final ball with the run in behind.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 740),
  ('Win it, dribble, delayed ball past mannequins', 'transition', 'passive', 'to_attack', 164, 164, 'Breaking from the Middle Zone: Practice 1', 'Mourinho (Real Madrid)', 'Counter from the middle zone after winning the ball, drawing defenders out and slipping a late final ball into the space created.', 'Three quarters of a pitch, a 44 x 34 yard grid in midfield with 3 mini goals at one end; 4 white attackers (4-2-3-1 front four) v 4 blue defenders in the grid, 4 mannequins as a back line in the final zone plus a keeper in the big goal.', 'Coach plays a long ball to the blues, who try to score in the mini goals while the whites press as a unit. When the whites win it they break out of the grid; one carries the ball up to the mannequins while team-mates run in behind them for the pass and finish.', 'Blues must stay inside the grid.', NULL, 'Press together to win it fast; break at high tempo with one-touch combinations; time runs and passes together.', '4v4 + GK, 4 mannequins', 9, 9, '44 x 34 yards', 40.2, 31.1, NULL, true, true, true, NULL, 750),
  ('Win it, dribble, delayed pass v real back four', 'transition', 'opposed', 'to_attack', 165, 165, 'Breaking from the Middle Zone: Practice 2', 'Mourinho (Real Madrid)', 'Same counter from the middle zone, now finishing against live defenders.', 'As practice 1 but the mannequins are replaced by 4 real defenders in the final zone.', 'Whites press the blues in the grid, win it, break out, carry the ball at the back four and release a delayed pass for a runner in behind to finish.', 'Defenders in the final zone step up in stages: passive, then active but not allowed to intercept a moving ball, then fully live.', NULL, NULL, '4v4 + 4 defenders + GK', 13, 13, '44 x 34 yards', 40.2, 31.1, NULL, true, true, true, NULL, 760),
  ('Win it, dribble, delayed pass v high line', 'transition', 'opposed', 'to_attack', 166, 166, 'Breaking from the Middle Zone: Practice 3', 'Mourinho (Real Madrid)', 'Break from midfield and play in behind a high defensive line.', 'A 40 x 40 yard area, 6v6 with both sides adding two central midfielders; mini goals at one end, final zone and big goal with keeper at the other.', 'When the whites win the ball they attack and slide a pass behind the defensive line to score in the final zone.', 'Blue defenders may not enter the final zone until the ball is played into it.', 'Defenders allowed into the final zone before the pass.', NULL, '6v6 + GK', 13, 13, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 770),
  ('Middle-zone keep-ball then counter on GO', 'transition', 'opposed', 'to_attack', 171, 171, 'Winning Possession in the Centre: Practice 1', 'Mourinho (Real Madrid)', 'Win the ball in the middle zone and launch very fast counter attacks.', '60 x 40 yards split into a 30 x 40 central zone and two 15 x 40 end zones with full goals and keepers; 9v9, both teams in a 2-2-3-1.', 'Both teams play keep-ball in the central zone (6-8 passes = 1 point). When the coach shouts GO just after a turnover, the team that just won it attacks the opposite goal fast while the other recovers.', 'Finish within 3-4 touches or 4-6 seconds after GO.', NULL, 'Keep it under pressure; react instantly to GO with smart runs; high tempo, accurate passing, quick finishing.', '9v9 inc. GKs', 18, 18, '60 x 40 yards', 54.9, 36.6, NULL, true, true, true, NULL, 780),
  ('Fast counter from the middle zone, 8v9', 'transition', 'opposed', 'to_attack', 172, 172, 'Winning Possession in the Centre: Practice 2', 'Mourinho (Real Madrid)', 'Win the ball in midfield and get in behind the defence quickly to score.', 'Full pitch width, a 40 x 65 yard area: 4 mini goals at one end, a high/safe zone and full goal with keeper at the other. Whites 8 in a 2-2-3-1, blues 9 in a 4-4 with their keeper.', 'The blue keeper starts; blues build out and try to score in the 4 mini goals. Whites press once the ball reaches the main area, win it and break into the high zone to score.', 'Whites cannot enter the safe zone while blues have the ball; whites limited touches, blues unlimited; whites have 4-5 seconds or 3-4 touches to move it from the middle into the high zone.', NULL, NULL, '8v9 + GK', 18, 18, '40 x 65 yards', 36.6, 59.4, NULL, true, true, true, NULL, 790),
  ('Fast counter from the middle zone, 9v9', 'transition', 'opposed', 'to_attack', 173, 173, 'Winning Possession in the Centre: Practice 3', 'Mourinho (Real Madrid)', 'Same fast-counter goal with full goals at both ends.', 'Same zoned area, 9v9 with a full goal and keeper at each end.', 'Blues always start; whites press once the ball enters the middle zone, win it and break fast to score.', 'Teams swap roles after 10 minutes.', NULL, NULL, '9v9 + 2 GKs', 20, 20, '40 x 65 yards', 36.6, 59.4, 20.0, true, true, true, NULL, 800),
  ('2v2 to 3v2 end-to-end duel game', 'one_v_one', 'opposed', 'to_attack', 175, 176, 'Overload Fast Break Attack: Practice 1', 'Mourinho (Real Madrid)', 'Fast break attacks using an extra runner to make a numerical advantage.', '25 x 25 yards with a full goal and keeper at each end; two teams of 6, spare players waiting on the lines; 2v2 on the pitch.', 'A keeper starts a 2v2; on the coach''s call a third player from the attacking team sprints on to make 3v2. When the attack ends the other keeper feeds his two, and a third team-mate joins from the line for 3v2 the other way.', 'After each attack one of the three attackers leaves and two stay on to defend.', 'Third runner joins without waiting for the coach''s call.', 'Waiting players switched on to support fast; creative combinations; always a free man to run into space; weighted final ball for a one-touch finish.', '2 teams of 6 + GKs', 14, 14, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 810),
  ('2-zone fast break support game', 'transition', 'opposed', 'to_attack', 177, 177, 'Overload Fast Break Attack: Practice 2', 'Mourinho (Real Madrid)', 'Quick support runs to turn a 2v2 into a 3v2 on the break.', '30 x 30 yards in two halves, full goal and keeper at each end; 2v2 in each half, spare players on the end lines.', 'A keeper passes to a team-mate in his half; the team feeds its two attackers in the far half and one player sprints up to make 3v2. When the attack ends, one attacker goes off and a new player comes on, and play continues the other way with roles reversed.', NULL, NULL, 'Strength and close control in 1v1/2v2; decide when to hold, dribble or pass; sprint forward after passing into the attacking half.', '2 teams + GKs', NULL, NULL, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 820),
  ('3v2 support play attack/defend duel', 'one_v_one', 'opposed', 'in_possession', 178, 178, 'Overload Fast Break Attack: Practice 3', 'Mourinho (Real Madrid)', 'Combine and finish quickly using a 3v2 overload.', '30 x 30 yards in two halves, full goals with keepers; 4 defenders (2 per half) and 7-8 attackers waiting at the sides.', 'Keeper feeds one of his two defenders against one attacker; they pass to an attacker in the other half and a side attacker joins from the nearest side for 3v2. Afterwards one attacker stays in the top half for a 2v1 from the keeper, and in the bottom half a player joins for 2v2; repeat from the other side.', NULL, NULL, NULL, '4 defenders + 7-8 attackers + 2 GKs', 13, 14, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 830),
  ('Shadow pass, press and fast break', 'transition', 'unopposed', 'to_attack', 184, 185, 'Transition from Attack to Defence & then Defence to Attack: Practice 1', 'Mourinho (Real Madrid)', 'Rehearse switching from attack to defence and straight back to attack in the high zone.', 'From the edge of the box to halfway; 8 players in a 2-2-3-1 plus a keeper, coach with balls.', 'The 8 keep the ball unopposed in shape. On the coach''s call the man on the ball becomes the opponent and the rest press him into correct positions without tackling. On the second call the coach plays a new ball to another player and the team breaks to score.', 'Attack must finish within 5-6 seconds.', NULL, 'Keep shape while passing, ready to press the ball; on the new ball, forward passes and timed runs into the box.', '8 + GK', 9, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 840),
  ('Keep-ball, win back, counter dynamic game', 'transition', 'opposed', 'to_defend', 186, 187, 'Transition from Attack to Defence & then Defence to Attack: Practice 2', 'Mourinho (Real Madrid)', 'Keep the ball under pressure, win it back within seconds when lost, then counter fast.', 'Edge of box to halfway; 3 mini goals on halfway and 2 on the sidelines; whites 8 in a 2-2-3-1 attack the big goal with a keeper, reds 8 in a 4-4.', 'Whites keep the ball (8 passes = 1 point). If reds win it, whites have 6-8 seconds to regain it, else reds score 1, and reds score 2 in any of the 5 mini goals. When whites win it back they must score in the big goal within 6-10 seconds for 2 points.', 'Whites unlimited touches in keep-ball, 1-2 touches when countering after a regain.', NULL, 'Fast transitions both ways; decisions under pressure; open body shape; check away before receiving; when to pass to feet or space and timing runs in behind.', '8v8 + GK', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 850),
  ('Counter dynamic game, 3 mini goals', 'transition', 'opposed', 'to_defend', 188, 188, 'Transition from Attack to Defence & then Defence to Attack: Practice 3', 'Mourinho (Real Madrid)', 'Same press-and-counter cycle with fewer targets for the opponent.', 'As practice 2 but the 2 sideline mini goals are removed, leaving 3 on halfway.', 'Whites keep it (8 passes = 1 point); reds win it and score in a mini goal (2) or keep it 6-8 seconds (1); whites regain and score within 6-10 seconds (2).', NULL, NULL, NULL, '8v8 + GK', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 860),
  ('Counter dynamic game, two big goals', 'transition', 'opposed', 'to_defend', 188, 188, 'Transition from Attack to Defence & then Defence to Attack: Practice 4', 'Mourinho (Real Madrid)', 'Press-and-counter cycle with a full goal for the opponent too.', 'As practice 3 but the mini goals are replaced by a full goal with keeper on the halfway line.', 'Same keep-ball, regain and counter sequence; whites score within 6-8 seconds after winning it for 2 points.', NULL, NULL, NULL, '8v8 + 2 GKs', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 870),
  ('3-zone keep-ball with forward passing', 'positional_game', 'opposed', 'in_possession', 193, 193, 'Passing Through the Midfield Line from the Back: Practice 1', 'Mourinho (Real Madrid)', 'Keep the ball in zones and pass forward through lines to the far zone.', '30 x 15 yards split into 3 equal zones with a 3v2 for the whites in each.', 'Whites keep the ball and move it from one end zone to the other (8 passes = 1, end to end and back = 2). If reds win it, the 3 whites in that zone must win it back at once.', 'Players stay in their zones. Reds score 1 for a pass to a team-mate in another zone or keeping it 6 seconds. Whites limited to 1-2 touches.', NULL, 'Keep the ball under pressure; open body shape and positioning to see the next pass.', '9v6', 15, 15, '30 x 15 yards', 27.4, 13.7, NULL, false, false, true, NULL, 880),
  ('6v6+2 three-zone forward passing game', 'positional_game', 'opposed', 'in_possession', 194, 194, 'Passing Through the Midfield Line from the Back: Practice 2', 'Mourinho (Real Madrid)', 'Zone keep-ball with neutrals and full role swaps on turnovers.', 'As practice 1 with an extra neutral in each zone.', 'Neutrals play for whichever team has the ball. When reds win it, reds and whites swap roles: reds go from defending to attacking and whites from attacking to defending.', NULL, NULL, NULL, '6v6 + 3 neutrals', NULL, NULL, '30 x 15 yards', 27.4, 13.7, NULL, false, false, true, NULL, 890),
  ('Through the midfield line transition game', 'positional_game', 'opposed', 'in_possession', 195, 195, 'Passing Through the Midfield Line from the Back: Practice 3', 'Mourinho (Real Madrid)', 'Keep the ball and pass through a midfield line into the far zone.', '60 x 30 yards: two 25 x 30 end zones and a 10 x 30 middle zone. 6 whites v 4 reds in one end, 2 reds in the middle, 6 whites in the other end.', 'Whites make 5 passes then try to play into the far zone (1 point) past the 2 middle reds. On success the 2 middle reds and 2 more reds cross to press, so it is 4 reds v 6 whites on the other side. If whites lose it in the end zone they hunt it back 6v4; if a middle red intercepts, it becomes 6 whites v 6 reds over a bigger area.', 'Whites 1-2 touches; middle reds stay in their zone.', 'Drop the 5-pass requirement to encourage early forward passes.', NULL, '12v6', 18, 18, '60 x 30 yards', 54.9, 27.4, NULL, false, false, true, NULL, 900),
  ('3-team midfield-line transition game', 'positional_game', 'opposed', 'in_possession', 196, 196, 'Passing Through the Midfield Line from the Back: Practice 4', 'Mourinho (Real Madrid)', 'Keep it, pass through the middle, and react to turnovers in a 3-team rotation.', 'Same 3-zone area; 3 teams of 6, two keep the ball in the end zones, one defends.', 'When defenders win it they pass to the team in the far end zone and all six move to the vacant end zone. The team that lost it sends 4 to press in the far zone and 2 into the middle to cut out passes.', NULL, NULL, NULL, '3 teams of 6', 18, 18, '60 x 30 yards', 54.9, 27.4, NULL, false, false, true, NULL, 910),
  ('Through the midfield line and finish, 5 zones', 'phase_of_play', 'opposed', 'in_possession', 197, 197, 'Passing Through the Midfield Line from the Back: Practice 5', 'Mourinho (Real Madrid)', 'Build out under pressure, pass through the middle and finish with an overload.', 'Full pitch, 50 yards wide, 5 zones with a 10-yard central zone; full goals and keepers. 10v10.', 'Whites build from the back 5v4, then pass into the far zone past 2 red interceptors; there it is 4v3+1 attacking the goal. If reds win it they counter 4v5. An interception in the middle sends the ball to the far keeper and teams swap roles.', 'Defenders cannot enter the end zone until the ball does. Touches: limited in the first zone, free in the other; or 3 touches first zone, 2 elsewhere, finish in 1.', NULL, NULL, '10v10', 20, 20, 'full pitch, 50 yards wide', NULL, 45.7, NULL, true, true, true, NULL, 920),
  ('9v9+2 position-specific 5-zone keep-ball', 'possession', 'opposed', 'in_possession', 201, 202, 'Building Up Play from the Back Through the Centre: Practice 1', 'Mourinho (Real Madrid)', 'Keep it in zones and use the overload in the centre.', '30 x 25 yards in 5 zones: a 15 x 15 centre box (3v3 + 2 neutrals), two 7.5 x 15 zones above and below (2v2), and two 15 x 5 side zones (1v1).', 'Both teams keep the ball under pressure (6 passes or 8 seconds = 1 point); moving it through all 5 zones without losing it = 2.', 'Option A: centre backs and wide players 2-3 touches, attackers and inside players free, neutrals 1 touch. Option B: centre backs, wide players and attackers free, neutrals and inside players 1 touch.', NULL, 'Centre: passes to feet, check away to make space, angle and distance of support, choose when to switch. Outside: strength and shielding in 1v1/2v2, time runs with passes, quick one-touch combos.', '9v9 + 2 neutrals', 20, 20, '30 x 25 yards', 27.4, 22.9, NULL, false, false, false, NULL, 930),
  ('Build-up in 1v1/2v2/3v3 zones', 'phase_of_play', 'opposed', 'in_possession', 203, 203, 'Building Up Play from the Back Through the Centre: Practice 2', 'Mourinho (Real Madrid)', 'Build from the back through zones and create overloads against an organised defence.', 'Full pitch divided into zones holding 1v1, 2v2 and 3v3 match-ups; keepers in both goals.', 'White keeper starts; whites build from the back, moving between zones to make overloads. If whites lose it, reds may roam freely and counter to score.', 'Whites may change zones, reds may not (until they win the ball).', NULL, 'As practice 1; forward runs, pass accuracy and weight, and timing runs in behind.', '10v10 + GKs', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 940),
  ('Build-up through a 4v4 central zone', 'phase_of_play', 'opposed', 'in_possession', 205, 205, 'Build Up Play with a 4v4 Situation on the Flank: Practice 1', 'Mourinho (Real Madrid)', 'Build through the centre from a typical 4v4 and finish 3v3.', 'Full pitch with a 20 x 20 yard central zone holding 4v4; near each box 2 attackers v 3 defenders and a keeper. 10v10.', 'The team starting with the ball in the centre passes to its 2 attackers outside the zone; one player then leaves the zone to join, making 3v3 to finish past the keeper.', NULL, NULL, 'Move well inside the zone to make space; get it to the attackers quickly.', '10v10', 20, 20, '20 x 20 yard central zone on a full pitch', 18.3, 18.3, NULL, true, true, true, NULL, 950),
  ('End-to-end 3v3+3 possession', 'positional_game', 'opposed', 'in_possession', 207, 207, 'Creating 1v1 and 2v1 Situations Near the Penalty Area: Practice 1', 'Mourinho (Real Madrid)', 'Possession, support and forward passing using a one-man advantage.', '12 x 12 yard middle with 3v3 plus 1 neutral, and a 12 x 4 yard end zone at each end holding a neutral.', 'Neutrals play for the team on the ball, helping move it from one end zone to the other (8 passes = 1, end to end and back = 2).', 'Neutrals 1 touch and others 2; or everyone 1 touch.', NULL, 'Quick, sharp one-touch combinations; right angle and distance of support; quality passing.', '3v3 + 3 neutrals', 9, 9, '12 x 12 yards plus two 12 x 4 end zones', 18.3, 11.0, NULL, false, false, true, NULL, 960),
  ('End-to-end 5v5+1 possession', 'positional_game', 'opposed', 'in_possession', 208, 208, 'Creating 1v1 and 2v1 Situations Near the Penalty Area: Practice 2', 'Mourinho (Real Madrid)', 'Same end-to-end possession with 1v1 battles in the end zones.', 'As practice 1: 3v3 plus a neutral in the middle, now a 1v1 in each end zone instead of a neutral.', 'Move the ball end to end with the neutral''s help (8 passes = 1, end to end and back = 2).', 'Neutral 2 touches, inside 3, outside free; or neutral 1, inside 2, outside free.', NULL, NULL, '5v5 + 1 neutral', 11, 11, '12 x 12 yards plus end zones', 18.3, 11.0, NULL, false, false, true, NULL, 970),
  ('9-zone dynamic 10v10 build-up game', 'conditioned_game', 'opposed', 'in_possession', 209, 209, 'Creating 1v1 and 2v1 Situations Near the Penalty Area: Practice 3', 'Mourinho (Real Madrid)', 'Build through the centre and create 2v1s by supporting across zones.', 'Full pitch marked into zones (two wide middle areas unused), equal numbers in each grid (1v1, 3v3 etc.), keepers in both goals.', 'Both teams try to score. Attackers may move between zones to support and make 2v1s; defenders stay in their zones. When the defending team wins it they can attack freely.', NULL, NULL, NULL, '10v10', 20, 20, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 980)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
